const searchProgrammes = `-- name: SearchProgrammes :many
SELECT id, channel_id, start_at, end_at, title, episode_title, season, episode, episode_label, air_date, is_new, is_live, is_repeat, hd, rating, categories, kind, series_key, description, description_source, picture, poster, picture_source, still, tmdb_kind, tmdb_id, feed_description, search FROM live_tv_programmes
WHERE end_at > ?1 AND search LIKE '%' || CAST(?2 AS TEXT) || '%'
ORDER BY start_at, channel_id
LIMIT ?3
`

type SearchProgrammesParams struct {
	NowAt    int64  `json:"now_at"`
	Word     string `json:"word"`
	RowLimit int64  `json:"row_limit"`
}

// Programmes still to end whose folded title and episode title hold the
// word, soonest first. The word is folded too, so it has no % or _ in it.
// The caller checks the other words and which channels the viewer may see.
func (q *Queries) SearchProgrammes(ctx context.Context, arg SearchProgrammesParams) ([]LiveTvProgramme, error) {
	rows, err := q.db.QueryContext(ctx, searchProgrammes, arg.NowAt, arg.Word, arg.RowLimit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []LiveTvProgramme{}
	for rows.Next() {
		var i LiveTvProgramme
		if err := rows.Scan(
			&i.ID,
			&i.ChannelID,
			&i.StartAt,
			&i.EndAt,
			&i.Title,
			&i.EpisodeTitle,
			&i.Season,
			&i.Episode,
			&i.EpisodeLabel,
			&i.AirDate,
			&i.IsNew,
			&i.IsLive,
			&i.IsRepeat,
			&i.Hd,
			&i.Rating,
			&i.Categories,
			&i.Kind,
			&i.SeriesKey,
			&i.Description,
			&i.DescriptionSource,
			&i.Picture,
			&i.Poster,
			&i.PictureSource,
			&i.Still,
			&i.TmdbKind,
			&i.TmdbID,
			&i.FeedDescription,
			&i.Search,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Close(); err != nil {
		return nil, err
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

