const upsertLiveReminder = `-- name: UpsertLiveReminder :one
INSERT INTO live_tv_reminders (id, user_id, number, programme_id, start_at, end_at, title, episode_title, season,
episode, series_key, state, created_at)
VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'set', ?)
ON CONFLICT(user_id, programme_id) DO UPDATE SET state = 'set'
RETURNING id, user_id, number, programme_id, start_at, end_at, title, episode_title, season, episode, series_key, state, created_at
`

type UpsertLiveReminderParams struct {
	ID           string `json:"id"`
	UserID       int64  `json:"user_id"`
	Number       string `json:"number"`
	ProgrammeID  string `json:"programme_id"`
	StartAt      int64  `json:"start_at"`
	EndAt        int64  `json:"end_at"`
	Title        string `json:"title"`
	EpisodeTitle string `json:"episode_title"`
	Season       *int64 `json:"season"`
	Episode      *int64 `json:"episode"`
	SeriesKey    string `json:"series_key"`
	CreatedAt    int64  `json:"created_at"`
}

func (q *Queries) UpsertLiveReminder(ctx context.Context, arg UpsertLiveReminderParams) (LiveTvReminder, error) {
	row := q.db.QueryRowContext(ctx, upsertLiveReminder,
		arg.ID,
		arg.UserID,
		arg.Number,
		arg.ProgrammeID,
		arg.StartAt,
		arg.EndAt,
		arg.Title,
		arg.EpisodeTitle,
		arg.Season,
		arg.Episode,
		arg.SeriesKey,
		arg.CreatedAt,
	)
	var i LiveTvReminder
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.Number,
		&i.ProgrammeID,
		&i.StartAt,
		&i.EndAt,
		&i.Title,
		&i.EpisodeTitle,
		&i.Season,
		&i.Episode,
		&i.SeriesKey,
		&i.State,
		&i.CreatedAt,
	)
	return i, err
}
